"""Dulcelind workshop: setup, project and Azure PostgreSQL."""
from course_model import *
from pathlib import Path
import re

def add(c,id,title,idea,example,explain,task,answer):
    item=lesson(c,id,title,idea,example,explain,q('Ce verificăm în această etapă?',answer,'Este suficient să schimbi CSS-ul','Tot codul se execută în browser'),task)
    task['revision']=3
    item['duration']='6-12 min'
    if task['mode']=='sql':task.update(contextCode=task.get('setup',''),contextLabel='Baza de date de la care pornești',expectedResult=task['expected'])
    if task['mode']=='ejs':task['inputData']=task.get('data',{})
    if task['mode']=='text':task.update(contextCode=example,contextLabel='Comenzile sau configurația de analizat')
    if task.get('tests'):task['requirements']=[t['label'] for t in task['tests']]
    return item

def guide(c,id,title,idea,example,explain,prompt,solution,answer):
    return add(c,id,title,idea,example,explain,text(prompt,solution),answer)

def setup_chapter():
    c=chapter('dulcelind-setup','Dulcelind · pregătirea pe calculator','Instalează uneltele, pornește Node.js și pregătește conexiunea PostgreSQL.','','code')
    rows=[
    ('runtime','Browser, Node.js și baza de date','Browserul afișează HTML; Node execută Express și EJS; PostgreSQL păstrează produsele.','GET /project/produse → Express → PostgreSQL → rows → EJS → HTML','EJS nu se deschide prin dublu clic. Browserul nu primește parola bazei. Exercițiile din curs folosesc date temporare, separate de Azure.','Ce componentă execută EJS?','Node.js','EJS se execută pe server'),
    ('install-node','Instalează Node.js','Descarcă Node.js 24 LTS de la nodejs.org/en/download și instalează-l cu npm și PATH.','node --version\nnpm --version','Deschide un terminal nou după instalare. Rulează comenzile în PowerShell, nu în consola browserului. Dacă node nu este recunoscut, verifică instalarea și repornește terminalul.','Scrie comanda care verifică versiunea Node.js.','node --version','Terminalul trebuie să găsească Node.js'),
    ('workspace','Creează directorul de lucru','Construiește într-un director nou și nu modifica exemplul consultat.','mkdir dulcelind\ncd dulcelind\nnpm init -y','npm init creează package.json în directorul curent. Deschide acel director în editor. Comenzile următoare se rulează acolo; nu ai nevoie de fișierele altcuiva.','Ce comandă inițializează package.json?','npm init -y','Directorul curent contează'),
    ('dependencies','Instalează bibliotecile','express, ejs și pg sunt biblioteci ale aplicației. sass și sharp pregătesc stilurile și imaginile.','npm install express@5 ejs pg sass sharp bootstrap@5.3.8','Păstrează package.json și lockfile-ul în Git; node_modules se regenerează. În repository-ul cursului păstrează managerul și lockfile-ul deja alese.','Scrie comanda pentru driverul PostgreSQL.','npm install pg','pg leagă Node de PostgreSQL'),
    ('modules','CommonJS și modulele .mjs','Dulcelind folosește require și module.exports în .js; platforma folosește import în .mjs.','const express=require("express");\nmodule.exports=app;','Nu adăuga type: module noului proiect dacă folosești această variantă .js; alternativ folosește .cjs. require is not defined poate indica sistemul de module greșit.','Ce expresie exportă aplicația CommonJS?','module.exports = app','Păstrează consecvent sintaxa modulelor'),
    ('folders','Organizează directoarele','Separă șabloanele, resursele publice și SQL-ul.','app.js\npackage.json\nviews/fragmente/\nviews/pagini/\nresurse/css/\nresurse/js/\nresurse/json/\nresurse/imagini/\ndata/','Creează directoarele din editor. views conține EJS; resurse conține fișiere publice. Un URL /project/resurse/css/general.css nu este o cale de pe disc. Aceste nume sunt ale aplicației construite aici.','Unde pui șabloanele EJS?','views','Șabloanele și resursele au roluri diferite'),
    ('first-server','Pornește primul server','Creează app.js și verifică Express înainte de a conecta baza.','const express=require("express");\nconst app=express();\napp.get("/",(req,res)=>res.send("Cofetaria Dulcelind"));\napp.listen(8090,"127.0.0.1");\n// Terminal: node app.js\n// Browser: http://127.0.0.1:8090/','Lasă terminalul deschis; Ctrl+C oprește procesul. EADDRINUSE înseamnă port ocupat: identifică procesul tău sau schimbă portul și URL-ul.','Ce comandă rulează app.js?','node app.js','Procesul trebuie să rămână pornit'),
    ('start-script','Configurează npm start','Completează scripts în package.json fără să elimini dependencies.','{"scripts":{"start":"node app.js"}}','În aplicația nouă npm start rulează app.js. În repository-ul cursului rulează scripts/serve.mjs pentru a servi și cursul și /project/. Nu înlocui scriptul acelui repository.','Cum rulezi scriptul start?','npm start','Scriptul start definește pornirea'),
    ('pg-install','Pregătește PostgreSQL','Pentru local instalează PostgreSQL de la postgresql.org/download/windows și pgAdmin. Pentru Azure folosești serverul alocat ție.','Host local: 127.0.0.1\nPort: 5432\nBază: dulcelind\nClient: pgAdmin sau psql','Alege o parolă proprie. În pgAdmin conectează serverul, creează baza dulcelind din Databases și deschide Query Tool pe ea. SQL-ul din browser merge și fără instalare, cu date resetate.','Cum se numește baza de antrenament?','dulcelind','Clientul SQL și serverul sunt componente diferite'),
    ('pg-identity','Verifică baza curentă','Confirmă baza înainte de import; un server poate avea mai multe baze.','SELECT current_database(),current_user;\nSELECT current_schema();','Verifică rezultatul și conexiunea selectată. În Azure, Dulcelind folosește baza cursului într-o schemă separată. Nu importa într-o bază aleasă din greșeală.','Ce funcție întoarce numele bazei curente?','current_database()','Verifică destinația înainte de import'),
    ('env-local','Configurează conexiunea locală','Datele reale se păstrează în mediul procesului, nu în codul trimis browserului.','$env:PROJECT_DATABASE_URL="postgresql://UTILIZATOR:PAROLA@127.0.0.1:5432/dulcelind"\nnpm start','Înlocuiește substituenții doar în terminalul tău. PowerShell transmite variabila procesului lansat din același terminal. Caracterele speciale din parolă se codifică în URL; poți folosi în schimb câmpuri separate în pg. Nu publica secrete în Git sau în editorul cursului.','Ce variabilă configurează conexiunea dedicată?','PROJECT_DATABASE_URL','Secretele nu se comit'),
    ('diagnose','Găsește cauza erorii','Verifică terminalul pentru server și DevTools pentru browser.','node nerecunoscut → instalare / PATH\nEADDRINUSE → port ocupat\nERR_CONNECTION_REFUSED → proces / port\nCSS 404 → URL greșit\nProduse 500 → log server și SQL','Network arată URL-ul și statusul resursei. Consola browserului arată erorile client; excepțiile Express apar în terminal. Nu schimba CSS ca să repari un răspuns 500.','Ce status indică o resursă CSS negăsită?','404','Erorile de rețea, CSS și SQL se diagnostichează separat')]
    for row in rows:guide(c,'dulc-'+row[0],*row[1:])
