    code='function solve(i){let ids=i.saved?i.saved.split(","):[];if(i.checked){if(!ids.includes(i.id))ids.push(i.id);}else ids=ids.filter(id=>id!==i.id);return ids.join(",");}'
    add(p,'project-cart','Coșul cos_virtual','Coșul memorează id-uri separate prin virgulă sub cheia cos_virtual.',code,'La încărcare citești lista și bifezi checkbox-urile .select-cos cu acel value. La schimbare salvezi lista. Nu schimba în JSON fără să adaptezi și citirea.',js('Actualizează coșul la bifare sau debifare, fără duplicate.',code,[(dict(saved='1,2',id='2',checked=True),'1,2'),(dict(saved='1,2',id='1',checked=False),'2'),(dict(saved='',id='6',checked=True),'6')]),'Citirea și scrierea păstrează același format')
    code='<div class="grid-produse"><% for(const prod of produse){ %><article class="produs"><h3><a href="/project/produs/<%= prod.id %>"><span class="val-nume"><%= prod.nume %></span></a></h3><span class="val-pret"><%= prod.pret %></span><span class="val-calorii"><%= prod.calorii %></span><span class="val-categorie"><%= prod.categorie %></span><input class="select-cos" type="checkbox" value="<%= prod.id %>"></article><% } %></div>'
    add(p,'project-ejs','Cardurile EJS din prajituri','Serverul transmite produse; fiecare prod are nume, pret, calorii și categorie.',code,'Selectorii val-nume și val-pret sunt contractul cu filtrele. NUMERIC poate ajunge ca text din pg: convertește-l înainte de calcule. Folosește <%= pentru escaparea valorilor.',ejs('Generează cardurile cu link, preț, calorii, categorie și checkbox.',code,dict(produse=produse),[count('.produs',3),exact('.val-nume','Savarină'),attr('h3 a','href','/project/produs/1'),attr('.select-cos','value','1')]),'Selectorii și câmpurile trebuie să corespundă')
    code='const express=require("express");const app=express();const produse=[{id:1,nume:"Savarină"}];app.get("/produs/:id",(req,res)=>{if(!/^\\d+$/.test(req.params.id)||!Number.isSafeInteger(Number(req.params.id)))return res.status(400).send("Cerere gresita");const prod=produse.find(p=>p.id===Number(req.params.id));if(!prod)return res.status(404).send("Produs inexistent");res.json(prod);});module.exports=app;'
    add(p,'project-route-id','Ruta /produs/:id','Ruta internă este /produs/:id; aplicația montată sub /project expune /project/produs/1.',code,'Laboratorul folosește o listă mică în loc de SQL pentru a testa ruta. În aplicație validezi id-ul și interoghezi baza cu $1. Id invalid produce 400, id valid inexistent produce 404.',express('Exportă aplicația cu produsul 1, id invalid 400 și inexistent 404.',code,[dict(path='/produs/1',json=dict(id=1,nume='Savarină')),dict(path='/produs/abc',status=400,bodyExpected='Cerere gresita'),dict(path='/produs/99',status=404,bodyExpected='Produs inexistent')]),'400 și 404 au cauze diferite')
    guide(p,'project-query','Interogarea produsului prin pg','Tabelul se numește prajituri; valoarea id se transmite separat.','const result=await pool.query("SELECT * FROM prajituri WHERE id = $1",[id]);\nconst prod=result.rows[0];','Nu concatena req.params.id în SQL. Dacă rows este gol, răspunde cu 404; altfel transmite prod către pagini/produs.','Scrie interogarea parametrizată pentru toate coloanele produsului după id.','SELECT * FROM prajituri WHERE id = $1','Datele clientului sunt parametri SQL')
    guide(p,'project-assets','Pregătește resursele înainte de pornire','Sass generează CSS și Sharp generează WebP. În integrarea cursului pregătirea are loc la build.','const css=sass.compile(inputScss).css;\nawait sharp(inputImage).resize(300).webp().toFile(outputImage);\n// Repository curs: npm run build:project','Creează directorul destinație înainte de generare. Browserul cere CSS, nu SCSS. Păstrează CSS-ul Bootstrap distribuit pentru aspect identic; reconstruiește-l intenționat după schimbări de stil.','Scrie comanda de build a resurselor în repository-ul cursului.','npm run build:project','Build-ul este separat de pornire')
    code='const express=require("express");const app=express();app.get("/defect",(req,res,next)=>next(new Error("Test")));app.use((req,res)=>res.status(404).send("Pagina inexistenta"));app.use((error,req,res,next)=>res.status(500).send("Eroare server"));module.exports=app;'
    add(p,'project-errors','Erorile 400, 404 și 500','În aplicația finală, textele și imaginile erorilor vin din erori.json și se afișează în pagini/eroare.ejs.',code,'Declară fallback-ul după rute. Handler-ul cu patru parametri primește excepțiile. Nu trimite parole sau detalii interne în răspunsul public.',express('Configurează 404 pentru o rută lipsă și 500 pentru /defect.',code,[dict(path='/lipsa',status=404,bodyExpected='Pagina inexistenta'),dict(path='/defect',status=500,bodyExpected='Eroare server')]),'Statusul HTTP se setează pe răspuns')
    guide(p,'project-checklist','Verifică site-ul cap-coadă','Testează rutele, datele și interacțiunile, nu doar pagina principală.','GET /project/ → 200\nGET /project/produse → 21 produse\nGET /project/produse?tip=patiserie → 7 produse\nGET /project/produse?tip=gelaterie → 5 produse\nGET /project/produs/1 → Savarină\nGET /project/produs/abc → 400\nGET /project/produs/999 → 404\nGET /project/health → PostgreSQL, 21','Verifică Network, imagini, meniu, filtre, sortare, Alt+C, coș după reload, temă și banner. Local fără conexiune poate apărea PGlite; în Azure trebuie PostgreSQL. Un răspuns 200 nu dovedește identitate vizuală.','Câte produse are catalogul original?','21','Verificăm separat date, funcții și aspect')
