def assembly_lessons(p):
    guide(p,'dulc-ejs-config','Configurează Express și EJS','Setează motorul și directorul views înainte de rute.','const express=require("express");\nconst path=require("node:path");\nconst app=express();\napp.set("view engine","ejs");\napp.set("views",path.join(__dirname,"views"));\napp.get("/",(req,res)=>res.render("pagini/index",{imagini:[]}));','Creează views/pagini/index.ejs cu structura paginii. Failed to lookup view cere verificarea directorului și a numelui. Linux distinge literele mari de cele mici.','Ce valoare setezi pentru view engine?','ejs','res.render generează HTML din EJS')
    code='<%- include("head") %><body><%- include("header") %><main><h2>Bine ati venit</h2></main><%- include("footer") %></body>'
    add(p,'dulc-partials','Reutilizează fragmentele','head conține metadate și linkuri CSS; header conține meniul; footer informațiile comune.',code,'În pagina locală folosești ../fragmente/head. Laboratorul furnizează fragmente în memorie, fără fișiere externe. Folosește <%- include pentru markup de încredere și <%= pentru date.',ejs('Include head, header și footer și adaugă main cu Bine ati venit.',code,{},[exact('title','Cofetaria Dulcelind'),exact('header h1','Cofetaria Dulcelind'),exact('main h2','Bine ati venit'),exact('footer','Contact')],partials={'head':'<head><title>Cofetaria Dulcelind</title></head>','header':'<header><h1>Cofetaria Dulcelind</h1></header>','footer':'<footer>Contact</footer>'}),'include evită duplicarea')
    guide(p,'dulc-static-mount','Montează resursele sub /project','Routerul interior servește /resurse, aplicația părinte îl montează pe /project.','const bakery=express();\nbakery.use("/resurse",express.static(path.join(__dirname,"resurse")));\nconst parent=express();\nparent.use("/project",bakery);\nparent.listen(8090,"127.0.0.1");','Browserul cere /project/resurse/css/general.css. Un link /resurse ar cere rădăcina domeniului. Prefixează linkurile în EJS sau rescrie URL-urile la randare, ca în integrarea cursului. În CSS căile relative se rezolvă din directorul fișierului CSS.','Scrie URL-ul complet al general.css.','/project/resurse/css/general.css','Ruta internă și prefixul public sunt diferite')
    guide(p,'dulc-home-sections','Completează pagina principală','Leagă ancorele meniului de secțiuni și construiește conținutul pe rând.','<main><div id="grid-pagina">\n<section id="welcome"><h2>Bine ati venit</h2></section>\n<section id="promotii"><h2>Promotii</h2></section>\n<section id="produse"><h2>Produse</h2></section>\n<section id="orar"><h2>Orar</h2></section>\n<section id="anunturi"><h2>Anunturi</h2></section>\n<section id="index-intrebari"><h2>Intrebari frecvente</h2></section>\n<section id="retete"><h2>Retete</h2></section>\n<section id="galerie-statica"><h2>Galerie</h2></section>\n</div></main>','Integrează în secțiuni componentele construite: program, detalii, imagini, iframe. Un id este unic în aceeași pagină. Catalogul este altă pagină, deci poate avea propriul id produse.','Ce id are secțiunea întrebărilor?','index-intrebari','Ancorele trebuie să găsească secțiunile')
    guide(p,'dulc-gallery-json','Galeria din JSON','galerie.json conține cale_galerie și imagini; fiecare imagine are fisier, titlu și luni.','const gallery=JSON.parse(await fs.readFile(jsonPath,"utf8"));\nconst luna=new Date().getMonth()+1;\nconst imagini=gallery.imagini.filter(im=>im.luni.includes(luna));','getMonth începe la 0, lunile JSON la 1. Construiește căile fisier și fisier_mediu, apoi transmite imagini către EJS. fs.readFile rulează pe server. În EJS folosește for pentru figure, img și figcaption.','Cu ce expresie obții luna 1–12?','new Date().getMonth()+1','JSON-ul și API-ul Date folosesc indici diferiți')
    guide(p,'dulc-recipes','Încarcă rețetele în iframe','Linkurile folosesc target identic cu name al iframe-ului.','<a href="https://www.youtube.com/embed/VIDEO_ID" target="ifr-video">Reteta</a>\n<iframe name="ifr-video" title="Retete video" src="https://www.youtube.com/embed/VIDEO_ID" allowfullscreen></iframe>','VIDEO_ID este un substituent pe care îl înlocuiești cu o rețetă disponibilă. Folosește adresa embed. Disponibilitatea YouTube nu poate fi dedusă doar dintr-un atribut corect.','Ce nume comun leagă target de iframe?','ifr-video','target trebuie să corespundă cu name')
    code='<article id="art-produs"><h2><%= prod.nume %></h2><p><%= prod.descriere %></p><img src="/project/resurse/imagini/produse/<%= prod.imagine %>" alt="<%= prod.nume %>"><p><%= prod.pret %> lei</p><ul><% for(const ingredient of (prod.ingrediente||[])){ %><li><%= ingredient %></li><% } %></ul></article>'
    add(p,'dulc-product-page','Pagina unui produs','Ruta transmite un singur prod, nu vectorul produse.',code,'Adaugă gramaj, calorii, categorie și pt_diabetici. Pentru ingrediente null folosește o listă goală. Imaginea păstrează prefixul /project și datele sunt escapate.',ejs('Construiește articolul și lista ingredientelor.',code,dict(prod=dict(nume='Savarină',descriere='Prajitura insiropata',imagine='aproximativ-savarina.jpg',pret='7.50',ingrediente=['faina','lapte'])),[exact('#art-produs h2','Savarină'),count('li',2),attr('img','src','/project/resurse/imagini/produse/aproximativ-savarina.jpg')]),'Pagina primește un singur produs')
    guide(p,'dulc-controls','Construiește controalele filtrelor','Păstrează id-urile pe care le citește produse.js.','<input id="inp-nume">\n<input name="gr_rad" type="radio" value="0:350" id="i_rad1">\n<input name="gr_rad" type="radio" value="350:700" id="i_rad2">\n<input name="gr_rad" type="radio" value="700:1000000000" id="i_rad3">\n<input name="gr_rad" type="radio" value="toate" id="i_rad4" checked>\n<input id="inp-pret" type="range" min="0" max="70" value="0">\n<span id="infoRange">(0)</span>\n<select id="inp-categorie"><option value="toate">toate</option></select>\n<button id="filtrare">Filtreaza</button>','La click citești valorile, aplici condițiile din project-filter și setezi display la block sau none. input.value este text: convertește prețurile și limitele calorice. Opțiunile categoriei vor veni din ENUM prin EJS.','Ce id are sliderul de preț minim?','inp-pret','Inputurile și scriptul folosesc aceleași id-uri')
    code='document.getElementById("filtrare").onclick=()=>{const prefix=document.getElementById("inp-nume").value.trim().toLowerCase();for(const card of document.querySelectorAll(".produs"))card.style.display=card.querySelector(".val-nume").textContent.trim().toLowerCase().startsWith(prefix)?"block":"none";};'
    add(p,'dulc-filter-dom','Aplică filtrul în DOM','Ascunde cardurile nepotrivite fără să le ștergi.',code,'Începe cu numele și adaugă caloriile, prețul și categoria. Filtrarea locală modifică afișarea, nu rândurile din PostgreSQL.',dom('La click afișează Savarină și ascunde Amandina.',code,'<input id="inp-nume" value="sav"><button id="filtrare">Filtreaza</button><article class="produs" id="sav"><span class="val-nume">Savarină</span></article><article class="produs" id="ama"><span class="val-nume">Amandina</span></article>',[prop('#sav','display','block'),prop('#ama','display','none')],[dict(type='click',selector='#filtrare')]),'Filtrarea schimbă afișarea')
    guide(p,'dulc-reset','Resetarea din exemplu','Resetarea originală golește numele, bifează toate caloriile și reafișează cardurile.','document.getElementById("inp-nume").value="";\ndocument.getElementById("i_rad4").checked=true;\nfor(const prod of document.querySelectorAll(".produs"))prod.style.display="block";','Sliderul și categoria nu sunt resetate de acel cod. Pentru identitate păstrezi comportamentul observat. O resetare completă ar modifica și sliderul, categoria și infoRange: este o îmbunătățire separată.','Ce radio bifează resetarea?','i_rad4','Descrie comportamentul real al codului')
    code='function solve(input){return input.filter(p=>p.display!=="none").reduce((sum,p)=>sum+Number(p.pret),0);}'
    add(p,'dulc-total','Alt+C: suma prețurilor afișate','Adună cardurile vizibile, nu produsele bifate în coș.',code,'În keydown verifică e.altKey și e.key.toLowerCase()==="c". Creează p#suma_preturi după p#p-suma doar dacă lipsește. Elimină-l după 2000 ms prin setTimeout. Number împiedică concatenarea textelor.',js('Returnează suma cardurilor care nu au display none.',code,[([dict(pret='7.50',display='block'),dict(pret='6.00',display='none')],7.5),([],0)]),'Suma folosește produsele afișate')
    code='document.getElementById("schimba_tema").onclick=()=>{if(document.body.classList.toggle("dark"))localStorage.setItem("tema","dark");else localStorage.removeItem("tema");};'
    add(p,'dulc-theme','Tema și persistența','Butonul schimba_tema comută body.dark și cheia tema.',code,'La încărcare aplică dark dacă cheia există. Rulează după crearea body, prin DOMContentLoaded sau defer. CSS pentru body.dark schimbă variabilele; stocarea singură nu modifică aspectul.',dom('La click adaugă dark pe body.',code,'<button id="schimba_tema">Tema</button>',[count('body.dark')],[dict(type='click',selector='#schimba_tema')]),'Tema combină CSS, DOM și stocare')
    guide(p,'dulc-css-order','Ordinea CSS și Bootstrap','Ordinea și media query influențează aspectul final.','<link rel="stylesheet" href="/project/resurse/css/general.css">\n<link rel="stylesheet" href="/project/resurse/css/general1000.css" media="(max-width:1000px)">\n<link rel="stylesheet" href="/project/resurse/css/general700.css" media="(max-width:700px)">\n<link rel="stylesheet" href="/project/resurse/css/nav.css">\n<link rel="stylesheet" href="/project/resurse/css/customizare_bootstrap.css">','Acesta este începutul ordinii: adaugă și nav1000, nav700 și galeria înainte de customizare_bootstrap, ca în pagina finală. Compară la aceeași temă, lățime și zoom. Verifică fonturile și CSS-urile în Network înainte să schimbi stilurile.','Ce extensie cere browserul pentru stylesheet?','.css','CSS-ul rezultat este cel afișat')
    guide(p,'dulc-assembly','Asamblează componentele','Reunește fragmentele, paginile, scripturile și rutele. Testează static înainte de SQL.','views/fragmente: head, header, footer\nviews/pagini: index, despre, produse, produs, eroare\nresurse/css: general, nav, galerie, produse, responsive\nresurse/js: produse, produse-cos, tema, schimba_tema, cookies\nresurse/json: galerie, erori\ndata: prajituri.sql, utilizatori.sql\napp.js: static, EJS, rute, date și erori','Fiecare etapă oferă o componentă, nu site-ul întreg printr-o singură copiere. Completează conținutul și stilurile, apoi verifică fiecare funcție. Înregistrare și Contact sunt linkuri substituent în aplicația originală; tabelele utilizatorilor nu implementează autentificare.','Ce șablon afișează un produs?','produs.ejs','Componentele trebuie verificate împreună')

def cloud_chapter():
    c=chapter('dulcelind-azure','Dulcelind · PostgreSQL real și Azure','Creează schema reală, conectează pg și publică aplicația cu verificări de funcționare.','','database')
    # Independent training data; the course never reads the separate example app.
    seed="CREATE TYPE tipuri_produse AS ENUM ('cofetarie','patiserie','gelaterie'); CREATE TYPE categ_prajitura AS ENUM ('comuna','dietetica'); CREATE TABLE prajituri(id serial PRIMARY KEY,nume text UNIQUE NOT NULL,pret numeric(8,2),calorii int,tip_produs tipuri_produse,categorie categ_prajitura,ingrediente text[]);"
    for i in range(1,22):
        name={1:'Savarină',2:'Amandina',6:'Nimic'}.get(i,'Item '+str(i))
        price={1:7.5,2:6,6:10}.get(i,i)
        kind='cofetarie' if i<=9 else 'patiserie' if i<=16 else 'gelaterie'
        seed+=f"INSERT INTO prajituri(nume,pret,calorii,tip_produs,categorie,ingrediente) VALUES ('{name}',{price},10,'{kind}','comuna',ARRAY['faina']);"
    seed=re.sub(r'^DROP TYPE IF EXISTS [^;]+;\s*','',seed,flags=re.M)
    setup='CREATE SCHEMA dulcelind; SET search_path TO dulcelind;\n'+seed
    def S(id,title,idea,code,expected,check=None,initial=setup):
        return add(c,id,title,idea,code,idea,sql('Rulează SQL pe baza temporară furnizată pentru rezultatul cerut.',code,expected,initial,check),'SQL-ul se execută pe date de antrenament')
    S('dulc-schema','Separă schema dulcelind','O schemă este un spațiu de nume în baza curentă. Nu creează un server nou și nu șterge public.','CREATE SCHEMA dulcelind; CREATE TABLE dulcelind.proba(id int); INSERT INTO dulcelind.proba VALUES(1); SELECT id FROM dulcelind.proba;',[dict(id=1)],initial='')
    S('dulc-enum','Tipurile exacte ale produselor','tipuri_produse permite cofetarie, patiserie și gelaterie. Tipurile și tabelele sunt create în aceeași schemă.','SELECT unnest(enum_range(NULL::tipuri_produse))::text AS tip;',[dict(tip=x) for x in ['cofetarie','patiserie','gelaterie']])
    S('dulc-table','Construiește tabelul prajituri','Începe cu id serial, nume unic, pret numeric(8,2), gramaj și calorii nenegative. Schema completă adaugă tip_produs, categorie, ingrediente, pt_diabetici, imagine și data_adaugare.','CREATE TABLE prajituri(id serial PRIMARY KEY,nume varchar(50) UNIQUE NOT NULL,pret numeric(8,2) NOT NULL,gramaj int CHECK(gramaj>=0),calorii int CHECK(calorii>=0));',[dict(nume='Savarină',pret='7.50')],check="INSERT INTO prajituri(nume,pret,gramaj,calorii) VALUES('Savarină',7.5,200,400); SELECT nume,pret::text FROM prajituri;",initial='')
    S('dulc-seed','Verifică cele 21 de produse','Seed-ul creează datele inițiale. Aici ai în laborator SQL-ul real al catalogului, fără date de conectare.','SELECT count(*)::int AS total FROM prajituri;',[dict(total=21)])
    S('dulc-types-count','Verifică produsele fiecărui tip','Catalogul are 9 produse de cofetărie, 7 de patiserie și 5 de gelaterie. Cere explicit ordinea rezultatelor.','SELECT tip_produs::text AS tip,count(*)::int AS total FROM prajituri GROUP BY tip_produs ORDER BY tip;',[dict(tip='cofetarie',total=9),dict(tip='gelaterie',total=5),dict(tip='patiserie',total=7)])
    S('dulc-ingredients','Listele de ingrediente','PostgreSQL întoarce text[] ca vector. ANY verifică apartenența; EJS va itera ingredientele.',"SELECT nume FROM prajituri WHERE 'faina'=ANY(ingrediente) AND id=1;",[dict(nume='Savarină')])
    S('dulc-search-path','Schema curentă și search_path','Numele necalificat prajituri se rezolvă prin search_path. dulcelind.prajituri evită ambiguitatea cu public.','SET search_path TO dulcelind; SELECT nume FROM prajituri WHERE id=1;',[dict(nume='Savarină')])
    S('dulc-transaction','Anulează o modificare cu ROLLBACK','BEGIN deschide tranzacția. ROLLBACK anulează schimbarea; COMMIT o confirmă. Nu folosi DROP TYPE în inițializarea repetată.','BEGIN; UPDATE prajituri SET pret=99 WHERE id=1; ROLLBACK; SELECT pret::text FROM prajituri WHERE id=1;',[dict(pret='7.50')])
    S('dulc-idempotent','Păstrează datele existente','La reinițializare verifică existența tabelului înainte să inserezi seed-ul. Nu dubla și nu suprascrie produsele.',"SELECT to_regclass('dulcelind.prajituri')::text AS tabel;",[dict(tabel='prajituri')])
    rows=[
    ('pool','Creează un singur Pool','Pool reutilizează conexiunile între cereri; nu crea unul pentru fiecare produs.','const {Pool}=require("pg");\nconst pool=new Pool({\n host:process.env.AZURE_POSTGRESQL_HOST,\n port:Number(process.env.AZURE_POSTGRESQL_PORT||5432),\n user:process.env.AZURE_POSTGRESQL_USER,\n password:process.env.AZURE_POSTGRESQL_PASSWORD,\n database:process.env.AZURE_POSTGRESQL_DATABASE,\n ssl:{rejectUnauthorized:true},\n options:"-c search_path=dulcelind",\n connectionTimeoutMillis:5000\n});','Exemplul este pentru Azure cu TLS. Pentru PostgreSQL local configurează politica TLS potrivită instalării. Nu apela pool.end după fiecare request; îl închizi la oprirea aplicației.','Ce clasă din pg reutilizează conexiunile?','Pool','Un Pool deservește mai multe cereri'),
    ('list-route','Ruta citește SQL și randează EJS','/produse citește produsele și opțiunile ENUM, apoi transmite datele către pagină.','app.get("/produse",async(req,res,next)=>{\n try {\n  const result=await pool.query("SELECT * FROM prajituri ORDER BY id");\n  const categories=await pool.query("SELECT unnest(enum_range(NULL::categ_prajitura))");\n  res.render("pagini/produse",{produse:result.rows,optiuni:categories.rows});\n }catch(error){next(error);}\n});','Template-ul iterează produse pentru carduri și optiuni pentru option. opt.unnest este coloana întoarsă de interogare. await așteaptă rezultatul; fără el primești o promisiune.','Ce proprietate pg conține rândurile?','rows','Ruta trimite rows către EJS'),
    ('type-query','Filtrează tipul pe server','?tip=patiserie schimbă setul citit din SQL. Acceptă numai valori cunoscute și folosește parametri.','const allowed=["cofetarie","patiserie","gelaterie"];\nconst tip=req.query.tip;\nif(tip!==undefined&&(typeof tip!=="string"||!allowed.includes(tip)))return res.status(400).send("Cerere gresita");\nconst result=await pool.query("SELECT * FROM prajituri"+(tip?" WHERE tip_produs=$1":"")+" ORDER BY id",tip?[tip]:[]);','Filtrul SQL se aplică înainte de EJS. Filtrul JavaScript de nume, calorii și preț se aplică pe cardurile primite. Nu concatena tip în textul SQL.','Ce placeholder este primul parametru pg?','$1','SQL-ul și valorile sunt separate'),
    ('pool-transaction','O tranzacție, aceeași conexiune','Rezervă un client din Pool și eliberează-l în finally.','const client=await pool.connect();\ntry{\n await client.query("BEGIN");\n await client.query("SELECT pg_advisory_xact_lock(260019)");\n await client.query("CREATE SCHEMA IF NOT EXISTS dulcelind");\n // verifică tabelele și inițializează ce lipsește\n await client.query("COMMIT");\n}catch(error){await client.query("ROLLBACK");throw error;}\nfinally{client.release();}','pool.query poate alege clienți diferiți. Instrucțiunile unei tranzacții trebuie executate prin același client. Inițializarea aplicației folosește pg_advisory_xact_lock pentru a serializa procesele concurente; blocarea se eliberează la terminare.','Ce metodă returnează clientul rezervat în Pool?','client.release()','Tranzacția rămâne pe același client'),
    ('user-tables','Utilizatori și accesări','utilizatori are rol și username unic; accesari poate referi un utilizator.','CREATE TYPE roluri AS ENUM (\'admin\',\'moderator\',\'comun\');\nCREATE TABLE utilizatori(id serial PRIMARY KEY,username varchar(50) UNIQUE NOT NULL);\nCREATE TABLE accesari(id serial PRIMARY KEY,user_id int REFERENCES utilizatori(id),pagina varchar(500));','Acesta este un fragment al relației, nu schema completă. Restul include email, confirmare și alte câmpuri. O coloană parola nu implementează hash, înregistrare sau autentificare; acele fluxuri nu există în exemplul Dulcelind.','Ce tabel are cheia străină user_id?','accesari','O schemă nu este un sistem de autentificare'),
    ('azure-existing','Reutilizează resursele Azure','Identifică App Service-ul și serverul PostgreSQL deja folosite înainte să creezi alte resurse.','AZURE_POSTGRESQL_HOST\nAZURE_POSTGRESQL_PORT\nAZURE_POSTGRESQL_USER\nAZURE_POSTGRESQL_PASSWORD\nAZURE_POSTGRESQL_DATABASE','Dulcelind reutilizează aceste setări și schema dulcelind în aceeași bază. În contul propriu fără resurse poți crea App Service Linux pentru Node și PostgreSQL Flexible Server; verifică abonamentul și costul estimat înainte. Nu folosi baza colegilor pentru exerciții.','Ce setare indică numele bazei Azure?','AZURE_POSTGRESQL_DATABASE','Reutilizează configurația existentă potrivită'),
    ('azure-env','Configurează mediul App Service','În portalul App Service deschide Environment variables / App settings, setează valorile și salvează.','const host=process.env.AZURE_POSTGRESQL_HOST;\nconst database=process.env.AZURE_POSTGRESQL_DATABASE;\n// Nu afișa parola sau URL-ul complet în loguri.','Salvarea poate reporni aplicația. Setările rămân pe server: nu în site/course.js și nu în JavaScript-ul browserului. Dacă există Key Vault păstrează mecanismul configurat.','Prin ce obiect citește Node setările?','process.env','Datele de conectare rămân pe server'),
    ('tls','TLS și certificatul serverului','Conexiunea Azure folosește TLS cu verificarea identității serverului.','ssl:{rejectUnauthorized:true}','Dacă runtime-ul nu cunoaște CA-ul necesar, configurează certificatul cerut de furnizor. Nu folosi false ca soluție. Opțiunile SSL din URL pot suprascrie obiectul ssl: verifică regulile pg înainte să le combini.','Ce valoare păstrează verificarea rejectUnauthorized?','true','TLS verifică identitatea serverului'),
    ('network','Rețeaua dintre App Service și PostgreSQL','Cu acces public, permite în firewall sursele de ieșire ale aplicației. Cu acces privat, configurează integrarea de rețea și DNS.','App Service → outbound IP addresses\nPostgreSQL → Networking\nPort: 5432','Configurarea se face pe resursa Azure, nu într-un pg_hba local al aplicației. Nu deschide toate IP-urile pentru a ascunde problema. ETIMEDOUT și autentificarea greșită sunt cauze diferite.','Care este portul PostgreSQL implicit?','5432','Rețeaua și autentificarea se verifică separat'),
    ('permissions','Drepturi pentru schemă și date','Contul trebuie să se poată conecta și să creeze schema și tabelele la prima inițializare.','CREATE SCHEMA IF NOT EXISTS dulcelind;\n// În repository: npm run setup:project-db','Administratorul poate pregăti schema și datele înainte, apoi acorda aplicației drepturile necesare. Schema separă numele, nu este o barieră între conturi care au drepturi asupra ambelor scheme. Inițializarea repetată nu trebuie să modifice produsele existente.','Ce comandă inițializează explicit baza proiectului?','npm run setup:project-db','Schema și permisiunile au roluri diferite'),
    ('azure-port','Portul furnizat de Azure','Folosește PORT și bind 0.0.0.0 în producție. Local poți folosi 8090 și 127.0.0.1.','const port=Number(process.env.PORT||8090);\nconst host=process.env.NODE_ENV==="production"?"0.0.0.0":"127.0.0.1";\napp.listen(port,host);','În repository-ul cursului runtimeSettings detectează și WEBSITE_SITE_NAME, iar startup rămâne npm start. Nu porni un listener separat în createApp. Un port fix poate face containerul inaccesibil.','Ce variabilă furnizează portul Azure?','PORT','Azure stabilește portul aplicației'),
    ('lazy','Păstrează cursul rapid','Încarcă EJS și aplicația cofetăriei numai la accesarea /project/.','let projectPromise;\nprojectPromise ||= createApp();\nconst app=await projectPromise;\n// Baza se deschide la catalog, produs sau health.','Păstrează promisiunea pentru a evita inițializări simultane repetate. Baza și imaginile nu trebuie să întârzie pagina cursului. Dacă inițializarea SQL eșuează, curăță conexiunea și permite o reîncercare controlată.','Ce prefix declanșează încărcarea Dulcelind?','/project/','Încărcarea proiectului nu blochează pornirea cursului'),
    ('pipeline','Build și publicare prin GitHub','Revizuiește modificările și secretele înainte de commit; apoi urmărește workflow-ul de publicare.','git status\ngit diff --check\n// Revizuiește și comite fișierele proiectului.\n// În acest repository push pe main declanșează GitHub Actions.\n// Build: npm run build:project','Nu comite .env, parole, node_modules sau datele unui server PostgreSQL local. Build-ul instalează și verifică aplicația pe Linux; nu publica node_modules de Windows, deoarece Sharp include dependențe native. Un workflow verde nu confirmă singur conexiunea SQL live.','Pe ce sistem pregătești dependențele pentru App Service Linux?','Linux','Verifică și build-ul și aplicația publicată'),
    ('health','Verifică PostgreSQL după publicare','Deschide /project/health după terminarea deployment-ului.','{"ready":true,"project":"Dulcelind","database":"PostgreSQL","products":21}','În Azure trebuie PostgreSQL, nu PGlite. Endpoint-ul verifică accesul la date, dar nu trebuie să afișeze host, user, parolă sau URL. Cursul are separat /api/health.','Ce valoare database confirmă motorul dorit?','PostgreSQL','Verificarea live urmează după deployment'),
    ('live-debug','Diagnostichează conexiunea live','Deschide App Service Log stream și reproduce cererea catalogului.','Missing setting → mediu\npassword authentication failed → cont / parolă\nETIMEDOUT → rețea / DNS / firewall\ncertificate error → TLS / CA\npermission denied → drepturi\nrelation prajituri does not exist → schema / seed / search_path','Nu publica loguri cu secrete. Compară /api/health și /project/health pentru a identifica serviciul afectat. PostgreSQL rămâne obligatoriu în producție, ca un fallback să nu mascheze problema.','Ce endpoint verifică baza cofetăriei?','/project/health','Cursul și baza se verifică separat'),
    ('live-parity','Compară funcțiile și aspectul','Compară la aceeași lățime, temă și zoom. Un răspuns 200 nu dovedește identitate vizuală.','Desktop: 1440px\nTabletă: 768px\nMobil: 390px\nNetwork: resurse locale fără 404\nCatalog: 21; patiserie: 7; gelaterie: 5','Verifică și prefixul numelui, prețul minim, limitele calorice, sortarea în ambele sensuri, Alt+C, coșul după reload, tema și bannerul. Fonturile externe și video au nevoie de acces la serviciile lor.','Este suficient HTTP 200 pentru identitate vizuală? Scrie da sau nu.','nu','Aspectul și funcțiile se verifică separat')]
    for row in rows:guide(c,'dulc-'+row[0],*row[1:])
    return c

def align():
    def rename(v):
        if isinstance(v,str):return v.replace('Sweet Corner','Cofetăria Dulcelind')
        if isinstance(v,list):return [rename(x) for x in v]
        if isinstance(v,dict):return {k:rename(x) for k,x in v.items()}
        return v
    for c in chapters:c.update(rename(c))
    setup_chapter()
    p=project_chapter()
    assembly_lessons(p)
    # Gallery months in the real JSON are Romanian names, not numeric indices.
    gallery=next(l for l in p['lessons'] if l['id']=='dulc-gallery-json')
    gallery.update(intro='galerie.json conține cale_galerie și imagini. Fiecare imagine are fisier, descriere și luni, cu nume românești.',
        example='const gallery=JSON.parse(await fs.readFile(jsonPath,"utf8"));\nconst luni=["ianuarie","februarie","martie","aprilie","mai","iunie","iulie","august","septembrie","octombrie","noiembrie","decembrie"];\nconst luna=luni[new Date().getMonth()];\nconst imagini=gallery.imagini.filter(im=>im.luni.includes(luna));',
        explain='getMonth întoarce 0–11, iar vectorul luni transformă indicele în numele din JSON. Construiește căile fisier și fisier_mediu pe server, apoi transmite imagini către EJS. În buclă afișezi descriere în figcaption și alt. Nu folosi im.titlu: acel câmp nu există în JSON.')
    gallery['task'].update(prompt='Ce expresie întoarce indicele 0–11 pentru luna curentă?',solution='new Date().getMonth()',contextCode=gallery['example'])
    gallery['hint']=gallery['explain'];gallery['quiz']['explanation']=gallery['explain']
    for l in p['lessons']:
        if l['id']=='project-gallery':
            for field in ['example','intro','explain','hint']:l[field]=l[field].replace('briose-frisca.jpg','briose-frisca.png')
            l['task']['solution']=l['task']['solution'].replace('briose-frisca.jpg','briose-frisca.png')
    guide(p,'dulc-cookies','Bannerul și cookie-ul acceptat_banner','La confirmare, cookies.js memorează acceptat_banner într-un cookie cu durată de 60000 ms.','const d=new Date(Date.now()+60000);\ndocument.cookie="acceptat_banner=true; expires="+d.toUTCString();\ndocument.getElementById("banner").style.display="none";',
        'La load citești document.cookie, separi perechile prin ; și cauți numele exact. Dacă există acceptat_banner, ascunzi bannerul. #ok_cookies confirmă alegerea. Nu folosi localStorage aici dacă vrei comportamentul original: cookie-ul expiră după un minut. Browserul poate avea politici proprii pentru cookie-uri.',
        'Ce nume are cookie-ul folosit de banner?','acceptat_banner','Cookie-ul are nume și expirare')
    order=['project-shell','dulc-ejs-config','dulc-partials','dulc-static-mount','project-menu','project-menu-action','dulc-home-sections','dulc-css-order','project-table','project-faq','project-picture','project-video','dulc-recipes','project-gallery','dulc-gallery-json','project-assets','project-grid','project-ejs','dulc-product-page','project-route-id','project-query','dulc-controls','project-filter','dulc-filter-dom','project-sort','dulc-reset','dulc-total','project-cart','dulc-theme','dulc-cookies','project-errors','dulc-assembly','project-checklist']
    assert set(order)=={l['id'] for l in p['lessons']}
    p['lessons'].sort(key=lambda l:order.index(l['id']))
    cloud_chapter()
